import React, { useState, useEffect } from 'react';
import { Helmet } from 'react-helmet-async';
import { toast } from 'react-hot-toast';
import {
  DocumentTextIcon,
  HeartIcon,
  CalendarIcon,
  ChartBarIcon,
  UserIcon,
  CloudArrowUpIcon,
  EyeIcon,
  ArrowDownTrayIcon,
  ArrowLeftIcon,
  PlusIcon,
  XMarkIcon
} from '@heroicons/react/24/outline';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { useNavigate } from 'react-router-dom';
import api from '../../services/api';

const HealthRecords = () => {
  const navigate = useNavigate();
  // const { user } = useSelector((state) => state.auth);
  const [activeTab, setActiveTab] = useState('overview');
  const [records, setRecords] = useState([]);
  const [vitals, setVitals] = useState([]);
  const [medications, setMedications] = useState([]);
  const [allergies, setAllergies] = useState([]);
  const [loading, setLoading] = useState(false);
  
  // Modal states
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showVitalsModal, setShowVitalsModal] = useState(false);
  const [showMedicationModal, setShowMedicationModal] = useState(false);
  const [showAllergyModal, setShowAllergyModal] = useState(false);
  
  // Form states
  const [uploadForm, setUploadForm] = useState({
    file: null,
    title: '',
    description: '',
    category: 'general'
  });
  
  const [vitalsForm, setVitalsForm] = useState({
    bloodPressure: '',
    heartRate: '',
    temperature: '',
    weight: '',
    height: '',
    notes: '',
    date: new Date().toISOString().split('T')[0]
  });
  
  const [medicationForm, setMedicationForm] = useState({
    medicationName: '',
    dosage: '',
    frequency: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    prescribedBy: '',
    notes: '',
    status: 'active'
  });
  
  const [allergyForm, setAllergyForm] = useState({
    allergen: '',
    severity: 'mild',
    reaction: '',
    diagnosedDate: new Date().toISOString().split('T')[0],
    notes: ''
  });

  // Fetch health records data
  useEffect(() => {
    fetchHealthRecords();
  }, []);

  const fetchHealthRecords = async () => {
    try {
      setLoading(true);
      const response = await api.get('/health-records');
      const healthRecords = response.data.data.healthRecords;
      
      // Separate records by type and sort by date (most recent first)
      const documents = healthRecords.filter(record => record.type === 'document')
        .sort((a, b) => new Date(b.date) - new Date(a.date));
      const vitalsData = healthRecords.filter(record => record.type === 'vitals')
        .sort((a, b) => new Date(b.date) - new Date(a.date));
      const medicationsData = healthRecords.filter(record => record.type === 'medication')
        .sort((a, b) => new Date(b.date) - new Date(a.date));
      const allergiesData = healthRecords.filter(record => record.type === 'allergy')
        .sort((a, b) => new Date(b.date) - new Date(a.date));
      
      setRecords(documents);
      setVitals(vitalsData);
      setMedications(medicationsData);
      setAllergies(allergiesData);
      
      // Debug logging
      console.log('Vitals data:', vitalsData);
      if (vitalsData.length > 0) {
        console.log('Latest vital:', vitalsData[0]);
      }
    } catch (error) {
      console.error('Error fetching health records:', error);
      toast.error('Failed to load health records');
    } finally {
      setLoading(false);
    }
  };

  // Handler functions
  const handleUploadSubmit = async (e) => {
    e.preventDefault();
    if (!uploadForm.file) {
      toast.error('Please select a file to upload');
      return;
    }

    try {
      setLoading(true);
      const formData = new FormData();
      formData.append('file', uploadForm.file);
      formData.append('title', uploadForm.title);
      formData.append('description', uploadForm.description);
      formData.append('category', uploadForm.category);

      await api.post('/health-records/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      toast.success('Health record uploaded successfully!');
      setShowUploadModal(false);
      setUploadForm({ file: null, title: '', description: '', category: 'general' });
      fetchHealthRecords();
    } catch (error) {
      console.error('Error uploading record:', error);
      toast.error('Failed to upload health record');
    } finally {
      setLoading(false);
    }
  };

  const handleVitalsSubmit = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      await api.post('/health-records/vitals', vitalsForm);
      toast.success('Vital signs added successfully!');
      setShowVitalsModal(false);
      setVitalsForm({
        bloodPressure: '',
        heartRate: '',
        temperature: '',
        weight: '',
        height: '',
        notes: '',
        date: new Date().toISOString().split('T')[0]
      });
      fetchHealthRecords();
    } catch (error) {
      console.error('Error adding vitals:', error);
      toast.error('Failed to add vital signs');
    } finally {
      setLoading(false);
    }
  };

  const handleMedicationSubmit = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      await api.post('/health-records/medications', medicationForm);
      toast.success('Medication added successfully!');
      setShowMedicationModal(false);
      setMedicationForm({
        medicationName: '',
        dosage: '',
        frequency: '',
        startDate: new Date().toISOString().split('T')[0],
        endDate: '',
        prescribedBy: '',
        notes: '',
        status: 'active'
      });
      fetchHealthRecords();
    } catch (error) {
      console.error('Error adding medication:', error);
      toast.error('Failed to add medication');
    } finally {
      setLoading(false);
    }
  };

  const handleAllergySubmit = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      await api.post('/health-records/allergies', allergyForm);
      toast.success('Allergy added successfully!');
      setShowAllergyModal(false);
      setAllergyForm({
        allergen: '',
        severity: 'mild',
        reaction: '',
        diagnosedDate: new Date().toISOString().split('T')[0],
        notes: ''
      });
      fetchHealthRecords();
    } catch (error) {
      console.error('Error adding allergy:', error);
      toast.error('Failed to add allergy');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status.toLowerCase()) {
      case 'normal':
        return 'text-green-600 bg-green-100';
      case 'active':
        return 'text-blue-600 bg-blue-100';
      case 'complete':
        return 'text-gray-600 bg-gray-100';
      default:
        return 'text-yellow-600 bg-yellow-100';
    }
  };

  const getSeverityColor = (severity) => {
    if (!severity) {
      return 'text-gray-600 bg-gray-100';
    }
    switch (severity.toLowerCase()) {
      case 'severe':
        return 'text-red-600 bg-red-100';
      case 'moderate':
        return 'text-yellow-600 bg-yellow-100';
      case 'mild':
        return 'text-green-600 bg-green-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  // Handler functions for view and download
  const handleViewRecord = (record) => {
    if (record.filePath || record.fileUrl) {
      // If it's a file, open in new tab
      const fileUrl = record.filePath || record.fileUrl;
      if (fileUrl.startsWith('http')) {
        window.open(fileUrl, '_blank');
      } else {
        // Construct the full URL for local files
        const fullUrl = `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/uploads/${fileUrl}`;
        window.open(fullUrl, '_blank');
      }
    } else {
      // Show record details in a modal or alert
      toast.info(`Record: ${record.title}\nDate: ${new Date(record.date || record.createdAt).toLocaleDateString()}\nDescription: ${record.description || 'No description available'}`);
    }
  };

  const handleDownloadRecord = async (record) => {
    try {
      if (record.filePath || record.fileUrl) {
        const fileUrl = record.filePath || record.fileUrl;
        let downloadUrl;
        
        if (fileUrl.startsWith('http')) {
          downloadUrl = fileUrl;
        } else {
          // Construct the full URL for local files
          downloadUrl = `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/uploads/${fileUrl}`;
        }
        
        // Create a temporary anchor element and trigger download
        const link = document.createElement('a');
        link.href = downloadUrl;
        link.download = record.title || 'medical-record';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        
        toast.success('Download started');
      } else {
        toast.error('No file available for download');
      }
    } catch (error) {
      console.error('Error downloading record:', error);
      toast.error('Failed to download record');
    }
  };

  const tabs = [
    { id: 'overview', name: 'Overview', icon: ChartBarIcon },
    { id: 'records', name: 'Medical Records', icon: DocumentTextIcon },
    { id: 'vitals', name: 'Vital Signs', icon: HeartIcon },
    { id: 'medications', name: 'Medications', icon: UserIcon },
    { id: 'allergies', name: 'Allergies', icon: CalendarIcon }
  ];

  return (
    <>
      <Helmet>
        <title>Health Records - MediConnect AI</title>
        <meta name="description" content="Manage and view your health records" />
      </Helmet>

      <DashboardLayout>
        <div className="bg-gray-50 min-h-full">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
            {/* Header */}
            <div className="mb-8">
              <button
                onClick={() => navigate('/patient')}
                className="flex items-center text-teal-600 hover:text-teal-700 mb-4"
              >
                <ArrowLeftIcon className="h-5 w-5 mr-2" />
                Back to Dashboard
              </button>
              <div className="flex justify-between items-center">
                <div>
                  <h1 className="text-3xl font-bold text-gray-900 flex items-center">
                    <DocumentTextIcon className="h-8 w-8 mr-3 text-teal-600" />
                    Health Records
                  </h1>
                  <p className="mt-2 text-gray-600">
                    Access and manage your medical information
                  </p>
                </div>
                <button 
                  onClick={() => setShowUploadModal(true)}
                  className="flex items-center px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors"
                >
                  <CloudArrowUpIcon className="h-5 w-5 mr-2" />
                  Upload Record
                </button>
              </div>
            </div>

            {/* Tabs */}
            <div className="mb-6">
              <div className="border-b border-gray-200">
                <nav className="-mb-px flex space-x-8">
                  {tabs.map((tab) => {
                    const Icon = tab.icon;
                    return (
                      <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`py-2 px-1 border-b-2 font-medium text-sm flex items-center ${
                          activeTab === tab.id
                            ? 'border-teal-500 text-teal-600'
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                        }`}
                      >
                        <Icon className="h-5 w-5 mr-2" />
                        {tab.name}
                      </button>
                    );
                  })}
                </nav>
              </div>
            </div>

            {/* Tab Content */}
            <div className="space-y-6">
              {/* Overview Tab */}
              {activeTab === 'overview' && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  {/* Quick Stats */}
                  <div className="lg:col-span-2 space-y-6">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                        <div className="flex items-center">
                          <DocumentTextIcon className="h-8 w-8 text-blue-600" />
                          <div className="ml-4">
                            <p className="text-sm font-medium text-gray-600">Total Records</p>
                            <p className="text-2xl font-bold text-gray-900">{records.length}</p>
                          </div>
                        </div>
                      </div>
                      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                        <div className="flex items-center">
                          <HeartIcon className="h-8 w-8 text-red-600" />
                          <div className="ml-4">
                            <p className="text-sm font-medium text-gray-600">Active Medications</p>
                            <p className="text-2xl font-bold text-gray-900">{medications.length}</p>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Recent Records */}
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200">
                      <div className="p-6">
                        <h3 className="text-lg font-semibold text-gray-900 mb-4">Recent Records</h3>
                        <div className="space-y-3">
                          {records.slice(0, 3).map((record) => (
                            <div key={record.id} className="flex items-center justify-between p-3 border border-gray-200 rounded-lg">
                              <div className="flex items-center">
                                <DocumentTextIcon className="h-6 w-6 text-gray-400 mr-3" />
                                <div>
                                  <p className="font-medium text-gray-900">{record.title}</p>
                                  <p className="text-sm text-gray-600">{record.provider} • {record.date}</p>
                                </div>
                              </div>
                              <span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(record.status)}`}>
                                {record.status}
                              </span>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Latest Vitals */}
